customCSS:
.t, .history { color: #93a1a1; }
.join { color: #859900; }
.part, .quit { color: #93a1a1; }
.kick, .error { color: #dc322f; }
.notice { color: #b58900; }
.action { color: #d33682; }
.mode, .nick, .topic, .server { color: #2aa198; }
.highlight { color: #657b83; background-color: #eee8d5; border-left: 3px solid #d33682; padding-left: 8px; }
.reply { color: #93a1a1; border-left: 2px solid #268bd2; padding-left: 6px; }
.oper { color: #fdf6e3; background-color: #b58900; }
.reactions { color: #268bd2; background-color: #eee8d5; }
.card { background-color: #eee8d5; border-color: #93a1a1; }
.card-title { color: #268bd2; }
.card-desc { color: #93a1a1; }
.daychange { color: #93a1a1; border-color: #eee8d5; }
